export function buildLbaSeasonData(roundLimit: number = 3): {
  season: string;
  round: number;
  teams: TeamStats[];
  players: PlayerStats[];
  completedGamesCount: number;
} {
  const maxRound = Math.min(Math.max(roundLimit, 1), 3);
  // Audit DNP / Minutaggi Minimi: blocca a 0 chiunque abbia meno di un minuto o DNP
  const auditedPlayers = LBA_PLAYERS_RAW.map((p) => {
    if (p.gamesPlayed === 0 || p.mpg < 1.0) {
      return {
        ...p,
        gamesPlayed: 0,
        mpg: 0,
        pts: 0,
        reb: 0,
        ast: 0,
        stl: 0,
        blk: 0,
        tov: 0,
        pf: 0,
        fga: 0,
        fgm: 0,
        fg2a: 0,
        fg2m: 0,
        fg3a: 0,
        fg3m: 0,
        fta: 0,
        ftm: 0,
        pir: 0,
        plusMinus: 0,
        tsPct: 0,
        efgPct: 0,
        usgPct: 0,
        astPct: 0,
        astToRatio: 0,
        tovPct: 0,
        orbPct: 0,
        drbPct: 0,
        trbPct: 0,
        ortg: 0,
        drtg: 0,
        netRtg: 0,
        gameScore: 0,
        bpm: 0,
        ptsPer100: 0,
        rebPer100: 0,
        astPer100: 0,
      };
    }
    return p;
  });

  return {
    season: '2026/2027',
    round: maxRound,
    teams: LBA_TEAMS_CALCULATED,
    players: auditedPlayers,
    completedGamesCount: maxRound * 8,
  };
}
